package alphametics

import (
	"errors"
	"math"
	"sort"
	"strings"
)

type letterInfo struct {
	ch      byte
	coeff   int64
	leading bool
}

var (
	errInvalid      = errors.New("invalid puzzle")
	errUnsatisfiable = errors.New("no solution")
	errOverflow     = errors.New("puzzle too large")
)

func isSpace(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' }

func isLetter(c byte) bool {
	return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z'
}

func parsePuzzle(puzzle string) ([]string, string, error) {
	if strings.Count(puzzle, "==") != 1 {
		return nil, "", errInvalid
	}
	parts := strings.SplitN(puzzle, "==", 2)
	addends, err := parseAddendSide(parts[0])
	if err != nil {
		return nil, "", err
	}
	result, err := parseResult(parts[1])
	if err != nil {
		return nil, "", err
	}
	return addends, result, nil
}

func parseAddendSide(s string) ([]string, error) {
	words := []string{}
	i := 0
	for {
		for i < len(s) && isSpace(s[i]) {
			i++
		}
		if i >= len(s) {
			return nil, errInvalid
		}
		start := i
		for i < len(s) && isLetter(s[i]) {
			i++
		}
		if start == i {
			return nil, errInvalid
		}
		words = append(words, s[start:i])
		for i < len(s) && isSpace(s[i]) {
			i++
		}
		if i >= len(s) {
			return words, nil
		}
		if s[i] != '+' {
			return nil, errInvalid
		}
		i++
	}
}

func parseResult(s string) (string, error) {
	i := 0
	for i < len(s) && isSpace(s[i]) {
		i++
	}
	start := i
	for i < len(s) && isLetter(s[i]) {
		i++
	}
	if start == i {
		return "", errInvalid
	}
	word := s[start:i]
	for i < len(s) && isSpace(s[i]) {
		i++
	}
	if i != len(s) {
		return "", errInvalid
	}
	return word, nil
}
